func envelopeRDR(b pdu.Body) (pdu.Envelope, error) {
	m, ok := b.(*RDR)
	if !ok || m == nil {
		return pdu.Envelope{}, validation.ErrType
	}
	var out pdu.Envelope
	out.SessionID = avp.Some(m.SessionID)
	out.AuthSessionState = avp.Some(m.AuthSessionState)
	out.Origin.Host = m.OriginHost
	out.Origin.Realm = m.OriginRealm
	out.DestinationHost = m.DestinationHost
	out.DestinationRealm = avp.Some(m.DestinationRealm)
	out.ProxyInfo = m.ProxyInfo
	return out, nil
}
