func completeRDR(b pdu.Body, env pdu.RequestEnvelope) (pdu.Body, error) {
	m, ok := b.(*RDR)
	if !ok || m == nil {
		return nil, validation.ErrType
	}
	out := cloneRDR(m)
	if env.OriginHost != "" {
		if out.OriginHost != "" && out.OriginHost != env.OriginHost {
			return nil, validation.At(avp.Key{VendorID: 0, Code: 264}, validation.ErrEnvelope)
		}
		out.OriginHost = avp.CloneString(env.OriginHost)
	}
	if env.OriginRealm != "" {
		if out.OriginRealm != "" && out.OriginRealm != env.OriginRealm {
			return nil, validation.At(avp.Key{VendorID: 0, Code: 296}, validation.ErrEnvelope)
		}
		out.OriginRealm = avp.CloneString(env.OriginRealm)
	}
	if env.DestinationHost != "" {
		if out.DestinationHost.Value != "" && out.DestinationHost.Value != env.DestinationHost {
			return nil, validation.At(avp.Key{VendorID: 0, Code: 293}, validation.ErrEnvelope)
		}
		out.DestinationHost.Value = avp.CloneString(env.DestinationHost)
		out.DestinationHost.Present = true
	}
	if env.DestinationRealm != "" {
		if out.DestinationRealm != "" && out.DestinationRealm != env.DestinationRealm {
			return nil, validation.At(avp.Key{VendorID: 0, Code: 283}, validation.ErrEnvelope)
		}
		out.DestinationRealm = avp.CloneString(env.DestinationRealm)
	}
	return out, nil
}

